(window.COURSE_SOURCES = window.COURSE_SOURCES || {})["sales-basics"] = "Read in full: The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0): chapter 6 sections 6.2 and 6.3; chapter 7 sections 7.2, 7.3 and 7.4 (the directory table inside 7.4 was skimmed); chapter 8 sections 8.2 to 8.5; chapter 9 sections 9.2 to 9.5; chapter 10 sections 10.2, 10.4, 10.5 and 10.6; chapter 11 sections 11.2 and 11.3; chapter 12 sections 12.2 and 12.3; chapter 4 sections 4.2 and 4.3. OpenStax Principles of Marketing 15.3. The ICO telephone marketing page. The Citizens Information (Ireland) page on unfair sales practices.\n\nRead in part, from search extracts: the ICO electronic mail marketing page, the ICO business-to-business marketing page, the ICO live-calls page and the ICO small-organisations marketing page, and the summary page of the Irish Data Protection Commission's FAQ on electronic direct marketing (its PDF was not opened).\n\nNot read: the textbook's \"Selling U\" job-search sections and chapters 1 to 3, 5 and 13 to 15 (chapter 13 on follow-up was not in the fetched copy, so follow-up draws on 7.2 and OpenStax); 10.3 (dress); UK consumer unfair-practice guidance on GOV.UK (the page requested returned 404); UK and Irish bribery and whistleblowing law; SPIN Selling by Rackham and the Moncrief and Marshall paper (both only cited through the textbook).\n\nLimits: the core textbook was written about 2009 to 2012 from a US viewpoint, so its statistics and company examples are dated, and its advice on persistent follow-up conflicts with UK and Irish rules. The course says so where it matters. This is not legal advice.\n";
(window.COURSE_SOURCEMAP = window.COURSE_SOURCEMAP || {})["sales-basics"] = {"modules": {"1": "What selling is: the seven steps and how people buy", "2": "Finding and qualifying prospects", "3": "Preparing and opening the conversation", "4": "Presenting: questions, value and proposals", "5": "Objections, closing and follow-up", "6": "Selling fairly: ethics and the law (UK and Ireland)", "cap": "Plan and role-play a first sales conversation"}, "title": "", "intro": "Read in full: The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0): chapter 6 sections 6.2 and 6.3; chapter 7 sections 7.2, 7.3 and 7.4 (the directory table inside 7.4 was skimmed); chapter 8 sections 8.2 to 8.5; chapter 9 sections 9.2 to 9.5; chapter 10 sections 10.2, 10.4, 10.5 and 10.6; chapter 11 sections 11.2 and 11.3; chapter 12 sections 12.2 and 12.3; chapter 4 sections 4.2 and 4.3. OpenStax Principles of Marketing 15.3. The ICO telephone marketing page. The Citizens Information (Ireland) page on unfair sales practices. Read in part, from search extracts: the ICO electronic mail marketing page, the ICO business-to-business marketing page, the ICO live-calls page and the ICO small-organisations marketing page, and the summary page of the Irish Data Protection Commission's FAQ on electronic direct marketing (its PDF was not opened). Not read: the textbook's \"Selling U\" job-search sections and chapters 1 to 3, 5 and 13 to 15 (chapter 13 on follow-up was not in the fetched copy, so follow-up draws on 7.2 and OpenStax); 10.3 (dress); UK consumer unfair-practice guidance on GOV.UK (the page requested returned 404); UK and Irish bribery and whistleblowing law; SPIN Selling by Rackham and the Moncrief and Marshall paper (both only cited through the textbook). Limits: the core textbook was written about 2009 to 2012 from a US viewpoint, so its statistics and company examples are dated, and its advice on persistent follow-up conflicts with UK and Irish rules. The course says so where it matters. This is not legal advice.", "standard": false, "books": [], "pages": [{"key": "openstax-selling", "status": "unknown", "name": "15.3 Steps in the Personal Selling Process, Principles of Marketing", "by": "Gomez Albrecht, Green and Hoffman, OpenStax, Rice University, CC BY-NC-SA 4.0, 2023", "modules": [1, 5], "note": "", "uses": [{"module": 1, "title": "What selling is: the seven steps and how people buy", "lessons": [{"title": "Selling is a process: the seven steps", "chapters": ["15.3 Steps in the Personal Selling Process, Principles of Marketing"], "points": ["The Power of Selling was written around 2009 to 2012 from a US viewpoint. The structure of selling is stable, but its dollar figures and technology examples are dated. OpenStax Principles of Marketing sets out the same seven steps."]}]}, {"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Objections are questions", "chapters": ["15.3 Steps in the Personal Selling Process, Principles of Marketing"], "points": ["OpenStax agrees that good research lets you avoid many objections, and that price is almost always raised."]}, {"title": "Negotiating, then following up", "chapters": ["15.3 Steps in the Personal Selling Process, Principles of Marketing"], "points": ["OpenStax calls it a critical step for repeat business, referrals and extra sales at the next order."]}]}], "origin": ""}, {"key": "friedman-hbs", "status": "part", "name": "John H. Patterson and the Sales Strategy of the National Cash Register Company, 1884 to 1922", "by": "Friedman, Harvard Business School Working Knowledge", "modules": [1, 2], "note": "The Harvard Business School excerpt of the Business History Review article, on the Primer", "uses": [{"module": 1, "title": "What selling is: the seven steps and how people buy", "lessons": [{"title": "The lecturer's method: John H. Patterson", "chapters": ["John H. Patterson and the Sales Strategy of the National Cash Register Company, 1884 to 1922 (the Harvard Business School excerpt of the Business History Review article, on the Primer,"], "points": ["We read the Harvard Business School excerpt of Friedman's Business History Review article in full. It quotes the Primer directly. We read the rest of the article in an earlier pass, but its page now returns only a stub, so claims taken from it are marked and were not re-checked.", "Do not credit him with the invention. Scripts were rare but not new: Henry B. Hyde's Hints for Agents (1859), booklets for Bible Society canvassers, and Bates Harrington's How 'Tis Done (1879) came before the first NCR Primer in 1887.", "See what the script covered. The first sales script, How I Sell National Cash Registers, was written by Patterson's brother-in-law Joseph Crane and told salesmen what to do while speaking, with an asterisk meaning point to the item.", "Follow the four steps. Approach (no mention of the register; offer to help the merchant raise profit), proposition (first description of the register and how it prevents theft and gives an accurate daily account), demonstration (at a hotel display or the branch office), and close.", "Read the closing advice. It said not to ask for an order but to take it for granted, asking 'what colour shall I make it?' or 'how soon do you want delivery?', then fill in the order blank and hand over the pen."]}]}, {"module": 2, "title": "Finding and qualifying prospects", "lessons": [{"title": "The lecturer's method: John H. Patterson", "chapters": ["John H. Patterson and the Sales Strategy of the National Cash Register Company, 1884 to 1922 (the Harvard Business School excerpt of the Business History Review article, on the Primer,"], "points": ["The Harvard Business School excerpt of Friedman's article states the management system in general terms.", "Meet and compare. He held conventions and thematic sales contests, and the excerpt describes a system covering everything from quota calculation and commission rates to motivating discouraged salesmen.", "Leave out the hostility. The excerpt says he pressured salesmen to rid their regions of competition, and the reports also tracked competitors the company aimed to knock out. Aggressive tactics against rivals are not a model here.", "Avoid hostile tactics against rivals."]}]}], "origin": ""}, {"key": "friedman-full", "status": "part", "name": "John H. Patterson and the sales strategy of the National Cash Register Company, 1884 to 1922", "by": "Friedman, Business History Review, via The Free Library", "modules": [1, 2], "note": "The full article, read in an earlier pass for the territories, reports and quotas; the page now returns only a stub, so those details were not re-checked", "uses": [{"module": 1, "title": "What selling is: the seven steps and how people buy", "lessons": [{"title": "The lecturer's method: John H. Patterson", "chapters": ["John H. Patterson and the sales strategy of the National Cash Register Company, 1884 to 1922 (the full article, read in an earlier pass for the territories, reports and quotas; the page now returns only a stub, so those details were not re-checked)"], "points": ["A former salesman, T. C. Henry, wrote in his 1913 book Tricks of the Cash Register Trust that every argument a merchant could raise had been thrashed out in the company's schools, and he called the company a shark."]}]}, {"module": 2, "title": "Finding and qualifying prospects", "lessons": [{"title": "The lecturer's method: John H. Patterson", "chapters": ["John H. Patterson and the sales strategy of the National Cash Register Company, 1884 to 1922 (the full article, read in an earlier pass for the territories, reports and quotas; the page now returns only a stub, so those details were not re-checked)"], "points": ["The details on territories, daily reports, the sales school and quotas come from the full article and from Britannica, which we read in an earlier pass; the full article's page now returns only a stub, so those details were not re-checked.", "Train before you send. He opened a sales school in 1894, with an initial course of six weeks.", "Record every call. Salesmen wrote daily reports listing the customers called on, the sales made and the prospects visited.", "Set a quota from a stated basis. Quotas were first set by the population of the territory, on his calculation that one register could be sold for every four hundred people, and later by the previous year's sales.", "The quota basis was crude, one register per 400 people, and it was replaced by past sales as experience grew. A target should come from your own record and move when the record does."]}]}], "origin": ""}, {"key": "ps-process", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [1, 2, 5, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 7.2 It's a Process: Seven Steps to Successful Selling", "uses": [{"module": 1, "title": "What selling is: the seven steps and how people buy", "lessons": [{"title": "Selling is a process: the seven steps", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.2 It's a Process: Seven Steps to Successful Selling"], "points": ["Almost all selling follows the same sequence of steps, whatever is being sold.", "The textbook calls it a simple, logical framework that has been the accepted model for almost a hundred years.", "Salespeople adapt the details as culture and technology change, but the basic model has lasted.", "Find people or companies who might buy, and check they have the desire and ability.", "Needs awareness: the buyer notices a need."]}]}, {"module": 2, "title": "Finding and qualifying prospects", "lessons": [{"title": "Why prospecting comes first: leads, prospects and the funnel", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.2 It's a Process: Seven Steps to Successful Selling"], "points": ["A lead is a potential buyer. A prospect is a lead who has been qualified as ready, willing and able to buy.", "A lead is a potential buyer; a prospect has been qualified."]}]}, {"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Negotiating, then following up", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.2 It's a Process: Seven Steps to Successful Selling"], "points": ["Following up is a step, not an afterthought. It includes confirming delivery or installation, checking satisfaction, and asking about new needs.", "Check in when the product has been used, and ask how it is going.", "Contact after the sale to ensure satisfaction and learn about new needs.", "Follow-up leads to satisfaction, retention and referrals."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.2 It's a Process: Seven Steps to Successful Selling"], "points": ["What you will send and when."]}]}], "origin": ""}, {"key": "ps-buying", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [1], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 6.2 Buying 101", "uses": [{"module": 1, "title": "What selling is: the seven steps and how people buy", "lessons": [{"title": "Why people buy: needs, wants and emotion", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 6.2 Buying 101"], "points": ["Understanding why customers buy can change how you sell.", "Needs are essentials such as food, shelter, clothing, transport and health care.", "Wants improve quality of life but are not required to exist, such as holidays and fashion.", "The objective, tangible aspects of a product.", "The subjective aspects of a product."]}, {"title": "Consumers and businesses: who is buying?", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 6.2 Buying 101"], "points": ["B2C means business-to-consumer: the buyer is the end user, or buys for a household or friend.", "B2B means business-to-business: the buyer purchases to produce, resell or run an organisation.", "B2B buyers may be producers, resellers or organisations such as government and non-profit bodies.", "May or may not be budgeted.", "Coordinated, with approval from many people."]}]}], "origin": ""}, {"key": "ps-buying2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [1, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 6.3 How the Buying Process Works", "uses": [{"module": 1, "title": "What selling is: the seven steps and how people buy", "lessons": [{"title": "The buying process, emotion and FAB", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 6.3 How the Buying Process Works"], "points": ["The traditional B2B buying process in this textbook has eight numbered stages: recognise the need, define it, develop specifications, search for suppliers, request proposals, evaluate proposals, decide, and evaluate after purchase.", "Learn needs through dialogue.", "Users and initiators clarify it.", "Share insights without breaking confidences.", "Outline exact requirements."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 6.3 How the Buying Process Works"], "points": ["A FAB statement and a simple cost-benefit or ROI."]}]}], "origin": ""}, {"key": "brit-patterson", "status": "unknown", "name": "John Henry Patterson", "by": "Britannica Money", "modules": [2], "note": "", "uses": [{"module": 2, "title": "Finding and qualifying prospects", "lessons": [{"title": "The lecturer's method: John H. Patterson", "chapters": ["John Henry Patterson"], "points": ["Give each person a territory. Patterson assigned each salesman an exclusive territory.", "The first two columns follow the sources. The last column is our adaptation."]}]}], "origin": ""}, {"key": "ps-prospect", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [2, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 7.3 Prospecting: A Vital Role in the Selling Process", "uses": [{"module": 2, "title": "Finding and qualifying prospects", "lessons": [{"title": "Why prospecting comes first: leads, prospects and the funnel", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.3 Prospecting: A Vital Role in the Selling Process"], "points": ["Prospecting is the most vital part of the selling process, because you cannot sell to people you have not identified.", "It is not a one-off job. Businesses lose customers every year, and new prospects are the only way to replace them and to grow.", "A lead is the only thing you can turn into a sale, so never write one off without qualifying it.", "The textbook cites older US surveys that most 'just looking' shoppers go on to buy. It reports that over two-thirds of shoppers who say they are just looking buy within a week, from a 2004 survey.", "It also reports that 30% to 50% of companies responding to business ads buy within one or two years, while sellers convert only 1% to 5% of inquiries."]}, {"title": "Qualifying: ready, willing and able", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.3 Prospecting: A Vital Role in the Selling Process"], "points": ["Do not judge by appearance. The textbook warns that a customer in torn jeans may still be qualified, and says you only know by asking specific questions."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.3 Prospecting: A Vital Role in the Selling Process"], "points": ["A one-sentence offer and a short ideal customer profile.", "Offer: appointment-reminder software for small physiotherapy clinics. Ideal customer: a clinic of two to six therapists that loses revenue to missed appointments."]}]}], "origin": ""}, {"key": "ps-prospect2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [2, 5, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 7.4 Go Fish: Resources to Help You Find Your Prospects", "uses": [{"module": 2, "title": "Finding and qualifying prospects", "lessons": [{"title": "Where leads come from: ten sources", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.4 Go Fish: Resources to Help You Find Your Prospects"], "points": ["Prospecting takes knowledge and creativity, and the best sources depend on your ideal customer. Put yourself in your prospect's shoes and ask where they go for information.", "The text says attracting a new customer costs five times as much as keeping one.", "People trust friends and reviews.", "Relationships bring referrals; trade bodies and professional sites help.", "Libraries and chambers of commerce list local businesses."]}, {"title": "Qualifying: ready, willing and able", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.4 Go Fish: Resources to Help You Find Your Prospects"], "points": ["Not every lead is worth a presentation. Qualifying means discovering whether a lead has the willingness and ability to buy.", "Choosing customers carefully saves time, and you do not want to write a long proposal for someone who was never genuinely interested.", "Does the prospect have a need?", "Do they have authority to decide?", "Do they have the resources?"]}, {"title": "Keeping records: information, intelligence and CRM", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.4 Go Fish: Resources to Help You Find Your Prospects"], "points": ["Good records turn prospecting into a system. A customer relationship management (CRM) system records a company's contacts with current and prospective customers.", "A simpler contact management system (CMS) tracks calls and meetings and may be enough if you are the only person dealing with each prospect.", "Every interaction, across people and channels.", "Calls and meetings and notes.", "Facts such as a company's size and location are information that competitors can find too."]}]}, {"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Negotiating, then following up", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.4 Go Fish: Resources to Help You Find Your Prospects"], "points": ["Ask happy customers for referrals, and thank them."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.4 Go Fish: Resources to Help You Find Your Prospects"], "points": ["Who, how you found them, and the five qualifying questions answered."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 7.4 Go Fish: Resources to Help You Find Your Prospects"], "points": ["Five qualifying questions answered; ideal customer profile; research sourced."]}]}], "origin": ""}, {"key": "carnegie-wiki", "status": "part", "name": "How to Win Friends and Influence People", "by": "Wikipedia", "modules": [3, "cap"], "note": "The lists of principles and the reception section, Wikipedia, secondary", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "The lecturer's method: Dale Carnegie", "chapters": ["How to Win Friends and Influence People (the lists of principles and the reception section"], "points": ["We did not read the book. The principles below are quoted as worded in the Wikipedia article's lists, and the reception comes from the same article. Britannica's note on genuine interest comes from an earlier pass.", "Know the book's shape. It was published by Simon & Schuster in late 1936, and the 1981 edition cut its sections from six to four. Carnegie called it an action-book.", "Start with the fundamentals. The first part says: don't criticise, condemn or complain; give honest and sincere appreciation; arouse in the other person an eager want.", "Learn the six ways. Become genuinely interested in other people; smile; remember a person's name is the sweetest and most important sound in any language; be a good listener and encourage others to talk about themselves; talk in terms of the other person's interest; make the other person feel important, and do it sincerely.", "Notice the qualifiers. 'Genuinely' and 'sincerely' are in the wording of the principles. Britannica notes the emphasis on genuine interest rather than flattery."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The lecturer's method: Dale Carnegie", "chapters": ["How to Win Friends and Influence People (the lists of principles and the reception section"], "points": ["We did not read the book. The principles below are quoted as worded in the Wikipedia article's lists, and the criticism comes from the same article.", "Avoid the argument. The only way to get the best of an argument is to avoid it; show respect for the other person's opinions and never say 'You're wrong.'", "Admit your own errors. If you're wrong, admit it quickly and emphatically; begin in a friendly way.", "Let them talk. Let the other person do a great deal of the talking, and try honestly to see things from their point of view.", "Give them the idea. Let the other person feel the idea is theirs; be sympathetic with their ideas and desires; appeal to the nobler motives."]}]}], "origin": ""}, {"key": "brit-carnegie-book", "status": "unknown", "name": "How to Win Friends and Influence People", "by": "Encyclopaedia Britannica", "modules": [3], "note": "", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "The lecturer's method: Dale Carnegie", "chapters": ["How to Win Friends and Influence People"], "points": ["Britannica notes the emphasis on genuine interest."]}]}], "origin": ""}, {"key": "ps-pre4", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 8.5 Prepare Your Presentation", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "Solve, don't sell: benefit statements and SMART objectives", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.5 Prepare Your Presentation"], "points": ["Prioritise and organise your agenda, personalise it to the customer, prepare visual aids and demonstrations, and practise your delivery."]}]}], "origin": ""}, {"key": "ps-pre1", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 8.2 Researching Your Prospect: Going Deeper", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "The preapproach: do your homework", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.2 Researching Your Prospect: Going Deeper"], "points": ["The preapproach is the process of finding out about a prospect before you contact them.", "Researching shows you care, gives you the power to sell adaptively, and puts you ahead of competitors.", "The text adds that people only buy from people they trust, and that trust begins with how well you prepared.", "Record what you learn on a precall planning worksheet. It lists the key facts, the purpose of the call, what you want to learn and what you plan to say.", "Writing goals down lets you measure whether the call worked."]}, {"title": "Solve, don't sell: benefit statements and SMART objectives", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.2 Researching Your Prospect: Going Deeper"], "points": ["What you offer that the prospect is willing to pay for."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.2 Researching Your Prospect: Going Deeper"], "points": ["Company, customers, buying situation and contact facts, with sources."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.2 Researching Your Prospect: Going Deeper"], "points": []}]}], "origin": ""}, {"key": "ps-pre2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 8.3 Solving, Not Selling", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "Solve, don't sell: benefit statements and SMART objectives", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.3 Solving, Not Selling"], "points": ["Great salespeople solve rather than sell. The text sells a camera one way to a teenager and another way to a grandmother: the same product, but a different problem and opportunity for each.", "Start with a needs and opportunity analysis: what problem does this person or organisation have, and what opportunity could you open up?", "Often you have to ask questions to uncover needs, and in business sales the aim of the first call is frequently only to identify needs, not to pitch.", "Then brainstorm solutions: generate ideas first and judge them later.", "Before the call, write two statements. A general benefit statement gives the big picture of how you can help, for example 'I have an idea that can help you lower your labour costs.'"]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.3 Solving, Not Selling"], "points": ["A SMART objective, a general and a specific benefit statement."]}]}], "origin": ""}, {"key": "ps-approach3", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3, 5], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 9.4 Choosing the Best Approach for the Situation", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "Choosing an approach, and handling gatekeepers and rejection", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.4 Choosing the Best Approach for the Situation"], "points": ["The book describes several ways to start. Choose the one that fits the situation, the customer and you, and mix them.", "Ask permission, then a leading or diagnostic question.", "Demonstrate or hand over the product.", "Mention a mutual contact (ask them first).", "Lead with a specific benefit."]}]}, {"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Negotiating, then following up", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.4 Choosing the Best Approach for the Situation"], "points": []}]}], "origin": ""}, {"key": "ps-approach1", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 9.2 First Impressions Make All the Difference", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "The approach: the six Cs and the first thirty seconds", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.2 First Impressions Make All the Difference"], "points": ["The approach is your first real contact with the prospect: a phone call, an email, a visit.", "You are not selling a product in the approach; you are introducing yourself and opening the way to a presentation.", "Preparation gives confidence.", "Know your product, set objectives, prepare a general benefit statement.", "Show you are competent and trustworthy."]}]}], "origin": ""}, {"key": "ps-approach2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 9.3 How to Start Off on the Right Foot", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "The approach: the six Cs and the first thirty seconds", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.3 How to Start Off on the Right Foot"], "points": ["Phone: give your name and purpose in the first twenty seconds, prepare a script, and ask 'Is this a good time?' rather than 'Did I catch you at a bad time?'.", "Phone: avoid opening with 'How are you today?' and avoid long explanations.", "Email: write a personal, well-written message, not something that looks like a template.", "In person, B2B: take your lead from the prospect on small talk and avoid openers that put them on guard.", "In person, B2C: talk to the customer, treat them as a guest, avoid 'Can I help you?' and avoid pressure."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.3 How to Start Off on the Right Foot"], "points": ["A 20-second opening with name, reason and a permission question."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.3 How to Start Off on the Right Foot"], "points": []}]}], "origin": ""}, {"key": "ps-pre3", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 8.4 Getting SMART about Your Sales Call", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "Solve, don't sell: benefit statements and SMART objectives", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.4 Getting SMART about Your Sales Call"], "points": ["Set an objective for each call. Success does not always mean closing; in complex sales it may be learning who the current supplier is or who decides.", "Make it SMART: Specific, Measurable, Actionable, Realistic and Time-bound.", "By the end of the meeting, know who the current vendors are, what issues the prospect has with them and what three priorities they have for future purchases.", "SMART goal for call one: 'By the end of the call, find out how many appointments are missed each week, who manages reminders today and agree a 20-minute demo date by Friday.' It is specific, measurable (three items), actionable, realistic and time-bound.", "Specific, Measurable, Actionable, Realistic, Time-bound."]}, {"title": "The approach: the six Cs and the first thirty seconds", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.4 Getting SMART about Your Sales Call"], "points": ["Note what is missing: a pitch. The goal of this call is a time to talk, per your SMART objective."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.4 Getting SMART about Your Sales Call"], "points": ["Objective: by the end of a 15-minute call, learn how many appointments are missed each week and agree a 20-minute demo date by Friday. Opening: name, reason, permission.", "A SMART objective is set during preparation."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 8.4 Getting SMART about Your Sales Call"], "points": ["SMART objective, benefit statements and a 20-second opening with permission."]}]}], "origin": ""}, {"key": "ps-approach4", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [3], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 9.5 Overcoming Barriers to Success", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "Choosing an approach, and handling gatekeepers and rejection", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 9.5 Overcoming Barriers to Success"], "points": ["A gatekeeper such as an assistant controls access to the decision maker. Treat them as part of the selling relationship, not as an obstacle.", "Give them the name of your organisation and the purpose of your call when they ask, learn their name and thank them.", "They often know how decisions are made and what their boss's schedule is.", "Rejection is part of selling. The text's remedies are to use language of certainty, role-play beforehand, make hard calls at the start of the day when you have most energy, and not to procrastinate.", "Most reasons for a no are not about you."]}]}], "origin": ""}, {"key": "ci-unfair", "status": "unknown", "name": "Unfair sales practices", "by": "Citizens Information (Ireland), page edited 16/06/2026", "modules": [3, 4, 5, 6, "cap"], "note": "", "uses": [{"module": 3, "title": "Preparing and opening the conversation", "lessons": [{"title": "Solve, don't sell: benefit statements and SMART objectives", "chapters": ["Unfair sales practices"], "points": ["A specific number such as 'cut costs by 10%' is a promise. In the UK and Ireland, false or unprovable claims can be a misleading sales practice. Only say what you can show. Module 6 explains."]}, {"title": "The approach: the six Cs and the first thirty seconds", "chapters": ["Unfair sales practices"], "points": ["Irish consumer law bans persistent unwanted offers by phone, email or other means.", "Irish law bans persistent unwanted communications; see Module 6."]}]}, {"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "Putting numbers on value, and writing a proposal", "chapters": ["Unfair sales practices"], "points": ["Do not hide price or key terms in a way that misleads. In Ireland, a sales practice is misleading if it leaves out or hides important information, or gives it unclearly or late."]}]}, {"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Objections are questions", "chapters": ["Unfair sales practices"], "points": ["Create urgency only with true facts. In Ireland, falsely saying an offer is available only for a limited time to pressure a consumer is a banned practice."]}, {"title": "Six strategies and six types of objection", "chapters": ["Unfair sales practices"], "points": ["One of the book's sample replies tells a buyer 'you really can't afford not to switch'. Phrases like that edge toward pressure. In Ireland, aggressive practices include tactics that intimidate or coerce a consumer."]}, {"title": "Closing: asking for the order", "chapters": ["Unfair sales practices"], "points": ["Where persistence ends and pressure begins matters. Irish consumer law bans creating the impression that a consumer cannot leave until they sign, and persistent unwanted offers."]}, {"title": "Negotiating, then following up", "chapters": ["Unfair sales practices"], "points": ["Walking away and trading concessions are normal. Misleading statements are not. In Ireland a sales practice can be misleading if it gives false information or leaves out important facts."]}]}, {"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Fair selling to consumers: misleading and aggressive practices", "chapters": ["Unfair sales practices"], "points": ["Consumer law in Ireland and the EU protects people buying goods, services and digital content against unfair sales practices.", "A practice is unfair if it misleads, pressures or is likely to distort the buying decision.", "Scope matters. Citizens Information says these consumer rules apply to sales between businesses and consumers, and do not cover sales between businesses or private sales between consumers.", "False or inaccurate information; hiding important information; giving it unclearly, in small print or too late; not identifying advertising.", "Intimidating or coercive tactics, threats or abusive language, exploiting vulnerable people, making it hard to cancel, threatening legal action without basis."]}, {"title": "Who may you contact? UK calls and emails", "chapters": ["Unfair sales practices"], "points": ["We read only the summary page, not the full guidance PDF, so use the DPC page itself for details. Irish consumer law also bans persistent unwanted offers."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["Unfair sales practices"], "points": ["Choose an offer whose numbers you can defend. Any ROI or saving you state must show its inputs, and any figure you cannot prove stays out."]}, {"title": "Rubric, role-play and review", "chapters": ["Unfair sales practices"], "points": ["No misleading or pressure claims, contact basis checked, opt-out honoured."]}]}], "origin": ""}, {"key": "selfridge", "status": "unknown", "name": "Harry Gordon Selfridge", "by": "Wikipedia", "modules": [4], "note": "", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "The lecturer's method: Harry Gordon Selfridge", "chapters": ["Harry Gordon Selfridge"], "points": ["The facts about the store come from Wikipedia.", "Wikipedia describes a store that opened on 15 March 1909, with goods laid out for customers to examine and features that included a silence room. It credits him with promoting shopping for pleasure rather than necessity.", "Wikipedia lists a silence room among the store's features."]}]}], "origin": ""}, {"key": "selfridges", "status": "unknown", "name": "Selfridges", "by": "Wikipedia", "modules": [4], "note": "", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "The lecturer's method: Harry Gordon Selfridge", "chapters": ["Selfridges"], "points": []}]}], "origin": ""}, {"key": "ps-pres2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [4, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 10.4 Making Your Presentation Work", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "Preparing to present", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.4 Making Your Presentation Work"], "points": ["The text recommends contingency plans such as handouts if equipment fails."]}, {"title": "The five steps of a presentation, and the tools", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.4 Making Your Presentation Work"], "points": ["One-to-one: adapt to the person's style and motivation.", "Group: watch group dynamics and who holds the most influence; find out attendees beforehand if you can.", "Slides: keep them brief and readable; use the 10/20/30 rule (ten slides, twenty minutes, thirty-point font).", "Demonstrations let prospects experience the product, involve them and prove performance.", "Video calls: treat them like in-person, remove distractions, and ask permission before recording."]}, {"title": "Putting numbers on value, and writing a proposal", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.4 Making Your Presentation Work"], "points": ["In business sales, closing often depends on whether the value delivered outweighs the cost.", "Two simple tools help: cost-benefit analysis and return on investment (ROI).", "$800 energy plus $200 water.", "$2,000 ÷ $3,000 × 100 = 66.7% (the text states 66%).", "Break-even is when cumulative savings reach the cost: $3,000 ÷ $1,000 = 3 years (our calculation from the text's figures). After that, each year adds $1,000 of saving."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.4 Making Your Presentation Work"], "points": []}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.4 Making Your Presentation Work"], "points": ["Role-play the call with a partner who plays the prospect and raises at least two objections. Record it if both of you agree, and tell the partner why you are recording and what you will do with the recording.", "The text says to ask permission before recording a video call."]}]}], "origin": ""}, {"key": "ps-pres4", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [4], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 10.6 Putting It All Together", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "The five steps of a presentation, and the tools", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.6 Putting It All Together"], "points": ["The text gives five steps for a sales presentation: build rapport, make a general benefit statement, make a specific benefit statement, present, then close and recap.", "Before you start, ask how much time you have and set expectations, for example thirty minutes to present and fifteen for discussion.", "A little small talk, confirm the time.", "Recap the last meeting and show the idea, not just a service.", "After investigating, show how you solve this buyer's problem."]}, {"title": "Putting numbers on value, and writing a proposal", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.6 Putting It All Together"], "points": ["A proposal sets out the specific terms of the sale.", "Good ones share elements: an introduction, the need, the solution and its benefits, costs, a timeline, a call to action and evidence you can deliver.", "Keep it focused on the prospect, clear and concise, easy to accept with an agreement attached, and checked for spelling.", "On timing, the text says do not raise price early; let the prospect connect with the solution first. It adds that if a prospect says 'just send a proposal', ask for a meeting to present it.", "A formal request for proposal (RFP) has set rules; follow its format and answer every question."]}]}], "origin": ""}, {"key": "ps-pres1", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [4], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 10.2 Preparation: Your Key to Success", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "Preparing to present", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.2 Preparation: Your Key to Success"], "points": ["The presentation is where qualifying, research and planning pay off, but in business sales it is mainly about starting a relationship.", "The text defines value in customer terms: ask questions, listen, and put the spotlight on solutions centred on the customer.", "It cites a study that presentations are often spread over several meetings, with the salesperson doing more listening than talking.", "Review your call objectives and picture how success would look.", "Rehearse out loud, but leave room to adapt. Even experienced presenters rehearse differently, and some do not rehearse the opening."]}]}], "origin": ""}, {"key": "ps-pres3", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [4, 5, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 10.5 How to Use SPIN Selling in Your Sales Call", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "SPIN: questions that uncover needs", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.5 How to Use SPIN Selling in Your Sales Call"], "points": ["SPIN selling comes from Neil Rackham's research on more than 35,000 sales calls, according to the textbook.", "It is customer-centred: you ask a lot of questions, let the buyer talk and listen.", "A call has four parts: opening, investigating, demonstrating capability and obtaining commitment. SPIN is named for the four question types used in investigating.", "Establish the facts of the buyer's present situation. Ask sparingly and research first.", "Which of your offices currently use DSL?"]}]}, {"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Closing: asking for the order", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.5 How to Use SPIN Selling in Your Sales Call"], "points": ["If she says she needs to check with her partner, offer to join a short call, a step that moves things forward."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.5 How to Use SPIN Selling in Your Sales Call"], "points": ["At least one SPIN question of each type."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 10.5 How to Use SPIN Selling in Your Sales Call"], "points": ["SPIN questions in order, FAB benefit tied to a stated need, honest numbers."]}]}], "origin": ""}, {"key": "selfridge-roc", "status": "unknown", "name": "The Romance of Commerce", "by": "H. Gordon Selfridge, Internet Archive", "modules": [4], "note": "1918): chapter I (honesty and advertising) and chapter XXIV (the department store's managers, windows and figures, read", "uses": [{"module": 4, "title": "Presenting: questions, value and proposals", "lessons": [{"title": "The lecturer's method: Harry Gordon Selfridge", "chapters": ["The Romance of Commerce (1918): chapter I (honesty and advertising) and chapter XXIV (the department store's managers, windows and figures) read"], "points": ["We read chapter I of his 1918 book The Romance of Commerce, on honesty and advertising, and chapter XXIV, on the managers of a department store. It is his own book, so the claims about his methods are his.", "Begin from the customer's standpoint. The manager of sales must put himself in the place of the public and think from the standpoint of the customer.", "Treat the display as a craft. Windows are studied with the care a stage manager gives stage effects, designed and dressed in a studio before they go into the window.", "Make the first contact good. Before the public complete their first transactions they must come into direct contact with a member of staff, and on how that transaction is conducted depends largely the future goodwill or disrespect of the customer.", "Let staff learn from errors. The precept for staff is 'Don't make the same mistake twice.'"]}]}], "origin": ""}, {"key": "ps-close2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [5, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 12.3 Collaborate to Negotiate", "uses": [{"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Negotiating, then following up", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 12.3 Collaborate to Negotiate"], "points": ["Negotiation is discussing an issue between parties with competing interests to reach agreement.", "The text frames it as win-win-win: the seller, the buyer and the relationship all gain.", "Price, contract length, service, terms and delivery can all be negotiated.", "Know your value; research the other side; set the minimum you will accept and be ready to walk away; open higher than that.", "Hold firm on the first offer; trade concessions (for every concession, get one); be specific and write it down; set deadlocks aside; do not get emotional."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 12.3 Collaborate to Negotiate"], "points": ["Next step set: demo on Thursday at 10:30. Follow-up email drafted with a written summary."]}]}], "origin": ""}, {"key": "ps-obj2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [5, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 11.3 Types of Objections and How to Handle Them", "uses": [{"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Six strategies and six types of objection", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 11.3 Types of Objections and How to Handle Them"], "points": ["'Can you share your concerns in this area?'", "'So you're concerned about capacity at peak times?'", "Shows you are listening and avoids overselling.", "Let customers speak for you.", "Use the objection to build trust."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 11.3 Types of Objections and How to Handle Them"], "points": ["Three likely objections with a restate, a question and evidence for each."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 11.3 Types of Objections and How to Handle Them"], "points": ["Restate-ask-evidence on two objections, a trial close, a clear next step and a follow-up plan.", "What to change: I answered the first price objection with a discount before asking what 'higher' meant. Next time: restate, ask, then show value."]}]}], "origin": ""}, {"key": "ps-close1", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [5, "cap"], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 12.2 Closing Starts at the Beginning", "uses": [{"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Closing: asking for the order", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 12.2 Closing Starts at the Beginning"], "points": ["Closing starts at the beginning of the selling process. The text says that if you wait for a proposal to close, it is too late.", "It is not high-pressure, trickery or manipulation.", "A trial close asks for an opinion; a closing question asks for a decision. Use trial closes early and often to learn when to ask.", "The text also contrasts 'Always Be Closing' with 'Always Be Opening': keep helping the customer identify and solve problems.", "The prospect is engaged, asks questions or reviews material."]}, {"title": "Negotiating, then following up", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 12.2 Closing Starts at the Beginning"], "points": ["A sale is the start of a relationship."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 12.2 Closing Starts at the Beginning"], "points": ["One trial close and one closing question that moves things forward."]}, {"title": "Rubric, role-play and review", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 12.2 Closing Starts at the Beginning"], "points": []}]}], "origin": ""}, {"key": "ps-obj1", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [5], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 11.2 Objections Are Opportunities to Build Relationships", "uses": [{"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "Objections are questions", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 11.2 Objections Are Opportunities to Build Relationships"], "points": ["An objection is a question or hesitation from the prospect about the product or the company.", "Usually it masks a request for more information.", "The textbook asks you to treat objections as invitations to continue to sell and as chances to find the true reason for resistance.", "It reports that a prospect says no an average of five times before buying, from a 2003 article.", "Treat that as a dated rule of thumb. The point is that at least one objection is normal."]}]}], "origin": ""}, {"key": "ziglar-sum", "status": "part", "name": "The Secrets of Closing the Sale by Zig Ziglar", "by": "The Investor's Podcast", "modules": [5], "note": "A book summary, read for its first 100,000 characters of about 133,000; secondary, the book was not read", "uses": [{"module": 5, "title": "Objections, closing and follow-up", "lessons": [{"title": "The lecturer's method: Zig Ziglar", "chapters": ["The Secrets of Closing the Sale by Zig Ziglar (a book summary, read for its first 100,000 characters of about 133,000; secondary, the book was not read)"], "points": ["We read the first 100,000 characters of a book summary of the 1984 book, about three-quarters of it. It is secondary, and nothing here is a quotation from Ziglar. Check the book before you quote him.", "Sort a no into its reason. The summary lists five: they feel they do not need what you sell; they do not have any money; they are in no rush; they do not want what you sell; they do not trust you.", "Treat many nos as requests for more. The summary says many people who say no are really saying 'tell me more', that you should not pressure them, and that you should give them new information so they can make a new decision.", "Check the price objection first. It says to repeat the objection as a question so the prospect has to defend it, and to verify that price is the real objection before responding.", "Do not argue. Objections thrive on opposition and die with agreement, so involve the prospect instead of lecturing."]}]}], "origin": ""}, {"key": "ico-b2b", "status": "unknown", "name": "Business-to-business marketing", "by": "Information Commissioner's Office, 22/05/2025 (read from extracts)", "modules": [6], "note": "", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Who may you contact? UK calls and emails", "chapters": ["Business-to-business marketing"], "points": ["Business-to-business marketing still touches personal data. A named email such as initials.lastname@company.com identifies a person, so UK GDPR applies.", "The ICO says consent and legitimate interests are the two lawful bases most relevant to B2B marketing, and legitimate interests needs a three-part test: identify the interest, show it is necessary, and balance it against the person's rights.", "Businesses can object, and you must then stop.", "E: a director's personal-style work email, j.murphy@company.example. This is personal data, so you also need a lawful basis such as consent or a documented legitimate interests test.", "A lawful basis needing a three-part test."]}, {"title": "Records, respect and a personal code", "chapters": ["Business-to-business marketing"], "points": ["Good records support honest, lawful selling. Under UK GDPR, if you can identify a person from the contact detail, even in a business role, it is personal data.", "Tell people who you are and why you hold their details when you collect them for marketing.", "So you can show your basis if challenged. (Our practice, following the ICO's lawful-basis approach.)", "Businesses and individuals can object.", "The ICO says businesses can object and you cannot keep marketing the personal data of someone who objected."]}]}], "origin": ""}, {"key": "springer-cadbury", "status": "unknown", "name": "Cocoa, Cadbury and Forced Labour in Sao Tome and Principe", "by": "Springer", "modules": [6], "note": "Chapter abstract", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "The lecturer's method: George Cadbury", "chapters": ["Cocoa, Cadbury and Forced Labour in Sao Tome and Principe (chapter abstract)"], "points": ["A scholarly chapter describes the firm spending a decade investigating, and an article on the episode describes it as an international scandal in which the firm was a major buyer. Critics argue that the delay mattered.", "Fair dealing has costs and takes time."]}]}], "origin": ""}, {"key": "ico-email", "status": "unknown", "name": "Electronic mail marketing", "by": "Information Commissioner's Office, 19/11/2024 (read from extracts)", "modules": [6, "cap"], "note": "Guide to PECR", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Who may you contact? UK calls and emails", "chapters": ["Electronic mail marketing (Guide to PECR)"], "points": ["In the UK, direct marketing by phone or electronic mail is regulated by the Privacy and Electronic Communications Regulations (PECR) as well as data protection law.", "Direct marketing means advertising or marketing material directed to particular individuals.", "Do not send unless they have specifically consented, or the 'soft opt-in' applies.", "You can email or text them, but it is good practice to keep a do-not-email list and screen new lists against it.", "They bought or discussed buying something similar, you gave a clear chance to opt out when collecting details and in every message. It does not apply to prospects or bought-in lists."]}, {"title": "Records, respect and a personal code", "chapters": ["Electronic mail marketing (Guide to PECR)"], "points": []}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["Electronic mail marketing (Guide to PECR)"], "points": []}, {"title": "Rubric, role-play and review", "chapters": ["Electronic mail marketing (Guide to PECR)"], "points": []}]}], "origin": ""}, {"key": "cadbury-1912", "status": "part", "name": "Experiments in Industrial Organization", "by": "Edward Cadbury, Internet Archive", "modules": [6], "note": "1912; the chapters on organisation, the Men's Works Committee and the suggestion scheme, the firm's own account, by Edward Cadbury", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "The lecturer's method: George Cadbury", "chapters": ["Experiments in Industrial Organization (1912; the chapters on organisation, the Men's Works Committee and the suggestion scheme read in part; the firm's own account, by Edward Cadbury)"], "points": ["The firm also had a standing way to look into complaints. Edward Cadbury's 1912 book says that when the Men's Works Committee began in 1905 its early work included the investigation of complaints received from customers, and that the organisation was designed so that no case of difficulty could arise without coming to the board's knowledge. That is the firm's own account."]}]}], "origin": ""}, {"key": "dpc-faq", "status": "unknown", "name": "FAQ on Consent for Electronic Direct Marketing", "by": "Data Protection Commission (Ireland), 01/05/2020 (summary page only; full PDF not read)", "modules": [6], "note": "", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Who may you contact? UK calls and emails", "chapters": ["FAQ on Consent for Electronic Direct Marketing"], "points": ["In Ireland, electronic direct marketing by phone, fax, text and email is covered by the GDPR and by the ePrivacy Regulations (SI 336 of 2011).", "The Data Protection Commission's guidance covers when consent is required, a limited exception for existing customers if specific requirements such as a clear opt-out are met, and how people can object."]}]}], "origin": ""}, {"key": "brit-cadbury", "status": "unknown", "name": "George Cadbury", "by": "Britannica Money", "modules": [6], "note": "", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "The lecturer's method: George Cadbury", "chapters": ["George Cadbury"], "points": []}]}], "origin": ""}, {"key": "jstor-higgs", "status": "unknown", "name": "Happiness and Work: Portuguese Peasants, British Laborers, African Contract Workers, and the Case of Sao Tome and Principe, 1901 to 1909", "by": "Catherine Higgs, International Labor and Working-Class History 86, 2014", "modules": [6], "note": "Abstract", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "The lecturer's method: George Cadbury", "chapters": ["Happiness and Work: Portuguese Peasants, British Laborers, African Contract Workers, and the Case of Sao Tome and Principe, 1901 to 1909 (abstract)"], "points": ["A critic would ask whether the second year of waiting on the Foreign Office's advice cost lives. The account does not say, and we do not either. Fair dealing includes keeping a record of why you waited."]}]}], "origin": ""}, {"key": "ico-live", "status": "unknown", "name": "How do we comply with the rules on live marketing calls?", "by": "Information Commissioner's Office, 10/09/2025 (read from an extract)", "modules": [6], "note": "", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Who may you contact? UK calls and emails", "chapters": ["How do we comply with the rules on live marketing calls?"], "points": ["Publicly listed numbers do not override TPS registration."]}]}], "origin": ""}, {"key": "ico-b2b-small", "status": "unknown", "name": "Marketing and data protection in detail", "by": "Information Commissioner's Office, advice for small organisations (read from an extract)", "modules": [6], "note": "", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Who may you contact? UK calls and emails", "chapters": ["Marketing and data protection in detail"], "points": []}, {"title": "Records, respect and a personal code", "chapters": ["Marketing and data protection in detail"], "points": ["A message that only informs, such as an appointment reminder, is a service message; it cannot contain anything promotional.", "Otherwise they count as marketing.", "A message that only informs, such as an appointment reminder, with no promotion.", "A service message is for information only and cannot contain anything promotional."]}]}], "origin": ""}, {"key": "ico-tel", "status": "unknown", "name": "Telephone marketing", "by": "Information Commissioner's Office, 19/11/2024; under review after the Data (Use and Access) Act", "modules": [6, "cap"], "note": "Guide to PECR", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Who may you contact? UK calls and emails", "chapters": ["Telephone marketing (Guide to PECR)"], "points": ["You must not make unsolicited live marketing calls to anyone who has told you they do not want your calls, or to numbers on the TPS or CTPS unless the person has specifically consented.", "Screen call lists against the TPS (individuals and some sole traders and partnerships) and the CTPS (companies and other corporate bodies), and keep your own do-not-call list.", "Always say who is calling, let your number display, and give a contact address or freephone number if asked.", "Automated recorded-message calls need specific consent.", "The ICO notes that its PECR guidance is under review because of the Data (Use and Access) Act, and may change."]}, {"title": "Records, respect and a personal code", "chapters": ["Telephone marketing (Guide to PECR)"], "points": ["The ICO says to keep one and screen against it.", "Contact rule: 'Before any marketing call, I check TPS and CTPS and my do-not-call list; before any email, I check whether the recipient is an individual or a company.'", "Your own record of people who object."]}]}, {"module": "cap", "title": "Plan and role-play a first sales conversation", "lessons": [{"title": "The brief and the call-plan template", "chapters": ["Telephone marketing (Guide to PECR)"], "points": ["The consent, TPS or CTPS check and any claims you will not make.", "Compliance: the clinic is a limited company, so the CTPS applies to calls; email goes to a general address with an opt-out.", "The fair-and-lawful section covers TPS and CTPS checks and claims."]}, {"title": "Rubric, role-play and review", "chapters": ["Telephone marketing (Guide to PECR)"], "points": ["The fair-and-lawful row checks consent, TPS or CTPS and claims."]}]}], "origin": ""}, {"key": "wa-cadbury", "status": "full", "name": "The Campaign against Island Slavery 1901 to 1908", "by": "William A. Cadbury Charitable Trust", "modules": [6], "note": "Adapted from John F. Crosfield; the Cadbury family's own account", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "The lecturer's method: George Cadbury", "chapters": ["The Campaign against Island Slavery 1901 to 1908 (adapted from John F. Crosfield; the Cadbury family's own account,"], "points": ["We read the Cadbury family trust's account of the campaign in full. It is adapted from a firm insider's history, so it is sympathetic, and the pace of the firm's action has been criticised. We also read a chapter on the firm's own organisation, including how it handled complaints, and Britannica, Wikipedia and two scholarly abstracts.", "Start from a rumour and check it. In 1901 William Cadbury heard of forced labour on cocoa plantations in the islands of São Tomé and Príncipe, and then the firm received particulars of an estate for sale that listed 200 labourers among its assets. He wrote to anti-slavery campaigners, missionaries and other chocolate makers.", "Hope for the better case, and look anyway. The account says he hoped to find a situation less bad than the evidence suggested, but went on gathering evidence, including from a Scottish missionary, and visited Lisbon in March 1903.", "Weigh walking away. The account says it would have been easy to stop buying and wash their hands of it, but William wanted any injustice put right, and only about 5 per cent of São Tomé cocoa went to England, so withdrawal alone probably would not have helped.", "Get an independent investigator. In 1904 Cadbury, Fry, Rowntree and Stollwerck chose Joseph Burtt to investigate. He reported mortality of over 10 per cent of young adults even on the best estates, and on one plantation 80 deaths among 150 newcomers."]}]}], "origin": ""}, {"key": "ps-ethics1", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [6], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 4.2 Business Ethics: Guiding Principles in Selling and in Life", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Ethics in selling: honesty, reputation and your word", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 4.2 Business Ethics: Guiding Principles in Selling and in Life"], "points": ["Ethics are the moral principles that define right and wrong. Business ethics is ethical behaviour applied to business.", "Sales is one of the most visible roles for ethics, because the salesperson meets the customer directly and what they say reflects the whole organisation.", "Disclose anything that affects value or desirability; withholding or falsifying is lying.", "Give full disclosure and let the customer decide. Do not decide for them.", "Not ethical; purchases follow the buyer's own process."]}, {"title": "Records, respect and a personal code", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 4.2 Business Ethics: Guiding Principles in Selling and in Life"], "points": ["Pair the checklist with your own code. The textbook suggests writing down your values and a personal mission statement as a guide.", "The six pillars of character it cites are trustworthiness, respect, responsibility, fairness, caring and citizenship.", "Selling honestly is not a handicap. The textbook says ethical behaviour is linked to profitability, and that honesty helps you stand out and build a reputation.", "Code: 'I will only claim what I can show. I will say what I do not know. I will stop contacting anyone who asks me to.'"]}]}], "origin": ""}, {"key": "ps-ethics2", "status": "unknown", "name": "The Power of Selling", "by": "Anonymous, LibreTexts", "modules": [6], "note": "Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge, 4.3 Policies, Practices, and Cultures", "uses": [{"module": 6, "title": "Selling fairly: ethics and the law (UK and Ireland)", "lessons": [{"title": "Ethics in selling: honesty, reputation and your word", "chapters": ["The Power of Selling (Business LibreTexts, CC BY-NC-SA 3.0, adapted from Flat World Knowledge), 4.3 Policies, Practices, and Cultures"], "points": ["Decline politely and tell your manager.", "Apply the checks: honest? The gift could look like an attempt to influence you. Policy? It breaks the rule. Paper test? A story about a buyer taking tickets looks bad.", "Decline politely, explain the policy and tell your manager.", "A private interest that appears to influence your duty."]}]}], "origin": ""}], "sections": [], "counts": {"full": 1, "part": 5, "search": 0, "none": 0, "unknown": 39}, "hasMd": true};
